import six
import logging
from abc import ABCMeta, abstractmethod
from ute_ue.utils.param_checker import tput_user_value2normalized
from taf.analyzer.iperf_throughput.facade import IperfThroughput


@six.add_metaclass(ABCMeta)
class ThroughputChecker(object):
    @abstractmethod
    def __init__(self, **kwargs):
        pass

    @abstractmethod
    def setup(self):
        pass

    @abstractmethod
    def calculate_throughput(self):
        pass

    @abstractmethod
    def teardown(self):
        pass


class FakeThroughputChecker(ThroughputChecker):
    def __init__(self):
        logging.info("Skip FakeThroughputChecker init method")

    def setup(self):
        logging.info("Skip FakeThroughputChecker setup method")

    def teardown(self):
        logging.info("Skip FakeThroughputChecker teardown method")

    def calculate_throughput(self):
        logging.info("skip here, "
                     "please check throughput on gnb with keywords outside of this library")
        return 0


class IperfThroughputChecker(ThroughputChecker):

    def __init__(self):
        super(IperfThroughputChecker, self).__init__()
        self._throughput_analyzer = None
        self._throughput = None

    def setup(self):
        self._throughput_analyzer = IperfThroughput()

    def create_iperf_throughput(self, file_path, protocol, time_range, column=None):
        if protocol == 'udp':
            self._throughput = self._throughput_analyzer.create_iperf_server_udp_throughput(column=column,
                                                                                            log=file_path,
                                                                                            time_range=time_range)
        else:
            self._throughput = self._throughput_analyzer.create_iperf_server_tcp_throughput(column=column,
                                                                                            log=file_path,
                                                                                            time_range=time_range)

    def create_iperf3_throughput(self, file_path, protocol, time_range, column=None):
        if protocol == 'udp':
            self._throughput = self._throughput_analyzer.create_iperf3_server_udp_throughput(column=column,
                                                                                             log=file_path,
                                                                                             time_range=time_range)
        else:
            self._throughput = self._throughput_analyzer.create_iperf3_server_tcp_throughput(column=column,
                                                                                             log=file_path,
                                                                                             time_range=time_range)

    def calculate_throughput(self):
        # iperf throughput is a list[dict], e.g.
        # [{'connection':
        #     {'connection_id': '3', 'server_addr': '10.44.35.224',
        #     'server_port': '50006', 'client_addr': '10.47.55.164', 'client_port': '40151'},
        # 'peak': {'value': 5060.0, 'unit': 'Kbits/sec'},
        # 'average': {'value': 5000.0, 'unit': 'Kbits/sec'},
        # 'minimum': {'value': 4950.0, 'unit': 'Kbits/sec'},
        # 'count': 120, 'interval':120.0}]

        self._throughput_analyzer.analyze(throughputs=[self._throughput, ])
        throughput_result = self._throughput_analyzer.get_throughput(throughput=self._throughput)
        return [item.to_dict() for item in throughput_result]

    def get_average_throughput(self):
        throughput_list = self.calculate_throughput()
        average_throughput_dict = throughput_list[0]['average']
        average_throughput = '{value}{unit}'.format(value=average_throughput_dict['value'],
                                                    unit=average_throughput_dict['unit'])
        normalized_average_throughput = tput_user_value2normalized(average_throughput)
        logging.info("Average throughput is {} Kbits/sec".format(normalized_average_throughput))
        return normalized_average_throughput

    def teardown(self):
        pass
